import { Logger } from '@migaia/logger';
import { color, level } from '@migaia/logger/plugins';

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  context: ['api'],
  plugins: [level({ level: 'info' }), color({ format: 'pretty', color: 'auto' })]
});

log.info('server listening on %d', 3000);
log.error('request failed', new Error('timeout'));

await log.flush(); // 确保上面这些日志真正落地了再退出/继续

import { Logger } from '@migaia/logger';
import { batch, http, level, process } from '@migaia/logger/plugins';

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  plugins: [
    level({ level: 'info' }),
    batch({ maxSize: 50, maxWaitMs: 1000 }),
    http({ url: 'https://logs.example/v1/entries', batch: { maxSize: 50 } }),
    process() // 进程退出/崩溃前自动 flush
  ]
});

log.onFailure(({ source, error }) => console.error(`[logger] ${source} failed`, error));

const log = new Logger({
  execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false },
  context: ['app', 'api'],
  topic: 'gateway',
  options: { service: 'gateway' },
  on: { before: (entry) => {} },
  pipeline: { mode: 'sync' },
  plugins: [level(), color()]
});

log.log('info', 'user updated', userId); // userId 是 console 参数
log.dispatchRaw({
  tag: 'info',
  message: 'user updated',
  meta: { userId },
  data: { requestId },
  context: ['api', 'users']
});

const audit = new Logger({ execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }, topic: 'audit' });
audit.useSink((entry) => sendToAuditSystem(entry));

const api = new Logger({ execution: { mutationTimeoutMs: false, pipelineDrainTimeoutMs: false }, topic: 'api' });
api.extends(audit);

api.info('user created'); // 同时经过 api 自己的 pipeline/sink，也完整转发给 audit

import { getLoggerRuntimeManager, setLoggerRuntimeManager } from '@migaia/logger';

const previous = getLoggerRuntimeManager();
const restore = setLoggerRuntimeManager({
  randomUUID: () => crypto.randomUUID(),
  defer: (task) => queueMicrotask(task),
  write: (text) => console.log(text),
  fetch: (url, init) => fetch(url, init)
});

try {
  // 在这段作用域内创建和使用的 Logger 都会用上面这份能力
} finally {
  restore(); // 恢复到替换之前的 runtime manager
}

